        根元素.style.setProperty('--背景颜色', '#f6f2eb');
        根元素.style.setProperty('--面板内容背景颜色', 'rgba(235, 228, 217, 0.9)');
        根元素.style.setProperty('--文本颜色', '#5c5243');
        根元素.style.setProperty('--高亮文本颜色', 'var(--主颜色)');
        根元素.style.setProperty('--边框颜色', 'rgba(183, 144, 87, 0.6)');
        根元素.style.setProperty('--字体', "'Noto Sans SC', 'Microsoft YaHei', 'SimHei', sans-serif");
        根元素.style.setProperty('--字体粗细-常规', '300');
        根元素.style.setProperty('--字体粗细-标题', '500');
        根元素.style.setProperty('--边框圆角', '6px');
        根元素.style.setProperty('--头像尺寸', '80px');
        根元素.style.setProperty('--头像边框颜色', 'var(--主颜色)');
        if(页眉 && 数据结构.区块数组 && 数据结构.区块数组.length > 0 && 数据结构.区块数组[0].项目 && 数据结构.区块数组[0].项目['名称']) {
          // 动态设置页眉为角色名，如果存在
           页眉.textContent = 数据结构.区块数组[0].项目['名称'] + " · 情报界面";
        } else if (页眉) {
           页眉.textContent = "角色情报";
        }
      }
      const 主颜色值 = getComputedStyle(根元素).getPropertyValue('--主颜色').trim();
      if (主颜色值.startsWith('#') && 主颜色值.length === 7) {
        const r = parseInt(主颜色值.slice(1,3), 16);
        const g = parseInt(主颜色值.slice(3,5), 16);
        const b = parseInt(主颜色值.slice(5,7), 16);
        根元素.style.setProperty('--主颜色-rgb', `${r},${g},${b}`);
      } else {
         根元素.style.setProperty('--主颜色-rgb', '183,144,87');
      }
    }

    function 渲染数据(数据结构) {
      // 先移除旧的区块和无数据占位符
      const 旧区块 = 内容区域.querySelectorAll('.数据区块');
      旧区块.forEach(块 => 块.remove());
      if (无数据占位区) 无数据占位区.style.display = 'none';


      if (!数据结构.区块数组 || 数据结构.区块数组.length === 0) {
        if (无数据占位区) {
            无数据占位区.textContent = '数据读取失败或格式错误。';
            无数据占位区.style.display = 'block';
        } else { // 如果没有预设的占位符区，动态创建一个
            const 临时无数据提示 = document.createElement('div');
            临时无数据提示.className = '无数据';
            临时无数据提示.textContent = '数据读取失败或格式错误。';
            内容区域.appendChild(临时无数据提示);
        }
        return;
      }

      数据结构.区块数组.forEach(区块 => {
        const 区块容器元素 = document.createElement('div');
        区块容器元素.className = '数据区块';

        // 如果区块是角色状态，并且有名称，尝试更新头像alt和页眉
        if (区块.名称 === "角色状态" && 区块.项目["名称"]) {
          const 头像图片元素 = 内容区域.querySelector('.角色头像图片');
          if (头像图片元素) {
              头像图片元素.alt = 区块.项目["名称"] + "头像";
          }
          if (页眉) { // 再次确保页眉更新
              页眉.textContent = 区块.项目["名称"] + " · 情报";
          }
        }


        let 区块HTML内容 = `<div class="数据区块标题">${区块.名称}</div>`;
        for (const 键名 in 区块.项目) {
          // 不再显示“名称”字段本身，因为它已用于页眉和头像alt
          if (键名.toLowerCase() === '名称' && 区块.名称 === "角色状态") continue;

          区块HTML内容 += `
            <div class="数据项">
              <span class="数据键">${键名}:</span>
              <span class="数据值">${区块.项目[键名].replace(/\\n/g, '<br>')}</span>
            </div>`;
        }
        区块容器元素.innerHTML = 区块HTML内容;
        内容区域.appendChild(区块容器元素); // 将新区块添加到头像之后
      });
    }

    const 原始数据文本 = 数据源容器.textContent.trim();
    const 已解析数据 = 解析数据(原始数据文本); // 移到此处，确保应用主题时能访问
    数据结构 = 已解析数据; // 将解析后的数据存到全局（脚本作用域内）变量

    if (原始数据文本) {
      应用主题(已解析数据.配置);
      渲染数据(已解析数据);
    } else {
        if (无数据占位区) {
             无数据占位区.textContent = '未接收到有效数据。';
             无数据占位区.style.display = 'block';
        } else {
            const 临时无数据提示 = document.createElement('div');
            临时无数据提示.className = '无数据';
            临时无数据提示.textContent = '未接收到有效数据。';
            内容区域.appendChild(临时无数据提示);
        }
    }
  });
  // 全局（脚本作用域）变量，用于在其他函数中访问解析后的数据
  let 数据结构 = {};
  </script>
</body>
</html>
